// 提交历史对话框的跨打开状态。
//
// 这里钉的是那条**看不见的**规则: 状态要活过组件卸载。曾经把它写成组件实例里的变量 (注释也
// 写着"模块作用域"), 于是每次重新打开都归零 —— 展开的提交、滚动位置、已取到的文件列表全丢,
// 而这不会报任何错。

import { describe, expect, it, beforeEach } from 'vitest';

import { clearHistoryState, historyStateFor } from '../src/git/history-state';

describe('historyStateFor', () => {
  beforeEach(() => {
    clearHistoryState();
  });

  it('同一个项目返回同一个对象 (状态就地累积)', () => {
    const first = historyStateFor('C:\\projects\\a');
    first.expanded = ['abc'];
    first.scrollTop = 240;

    const second = historyStateFor('C:\\projects\\a');
    expect(second).toBe(first);
    expect(second.expanded).toEqual(['abc']);
    expect(second.scrollTop).toBe(240);
  });

  it('换项目就换一份新状态, 不串到上一个项目', () => {
    const a = historyStateFor('C:\\projects\\a');
    a.expanded = ['abc'];

    const b = historyStateFor('C:\\projects\\b');
    expect(b).not.toBe(a);
    expect(b.projectPath).toBe('C:\\projects\\b');
    expect(b.expanded).toEqual([]);
    expect(b.scrollTop).toBe(0);
  });

  it('换走再换回来不会复活旧状态 (只记当前项目)', () => {
    historyStateFor('C:\\projects\\a').scrollTop = 120;
    historyStateFor('C:\\projects\\b');

    expect(historyStateFor('C:\\projects\\a').scrollTop).toBe(0);
  });
});

describe('clearHistoryState', () => {
  it('清掉之后重新取是空状态', () => {
    const state = historyStateFor('C:\\projects\\a');
    state.expanded = ['abc'];
    state.files = { abc: [] };

    clearHistoryState();

    const fresh = historyStateFor('C:\\projects\\a');
    expect(fresh).not.toBe(state);
    expect(fresh.expanded).toEqual([]);
    expect(fresh.files).toEqual({});
  });
});
